// x(t) = 3t^2 - 4t + 2 ; secant vs tangent
var f = function (s) { return 3 * s * s - 4 * s + 2; };
var df = function (s) { return 6 * s - 4; };

var t0 = p.t0;
var h = p.h;
var tMin = 0, tMax = 4;
var yMin = -1, yMax = 36;
var padL = 40, padR = 16, padT = 16, padB = 30;
var X = function (s) { return padL + (s - tMin) / (tMax - tMin) * (W - padL - padR); };
var Y = function (y) { return H - padB - (y - yMin) / (yMax - yMin) * (H - padT - padB); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, H - padB); ctx.lineTo(W - padR, H - padB);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("t (s)", W - padR - 34, H - padB + 20);
ctx.fillText("x (m)", 4, padT + 10);

// gridline at x = 0
ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(padL, Y(0)); ctx.lineTo(W - padR, Y(0)); ctx.stroke();
ctx.setLineDash([]);

// curve
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 200; i++) {
  var s = tMin + (tMax - tMin) * i / 200;
  if (i === 0) ctx.moveTo(X(s), Y(f(s))); else ctx.lineTo(X(s), Y(f(s)));
}
ctx.stroke();
ctx.lineWidth = 1;

var t1 = Math.min(tMax, t0 + h);
var mSec = (f(t1) - f(t0)) / (t1 - t0);
var mTan = df(t0);

// tangent line (dashed, spans the plot)
ctx.strokeStyle = C.rule;
ctx.setLineDash([5, 4]);
ctx.beginPath();
ctx.moveTo(X(tMin), Y(f(t0) + mTan * (tMin - t0)));
ctx.lineTo(X(tMax), Y(f(t0) + mTan * (tMax - t0)));
ctx.stroke();
ctx.setLineDash([]);

// secant line through the two marked points
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(X(tMin), Y(f(t0) + mSec * (tMin - t0)));
ctx.lineTo(X(tMax), Y(f(t0) + mSec * (tMax - t0)));
ctx.stroke();
ctx.lineWidth = 1;

// rise / run box
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(X(t0), Y(f(t0))); ctx.lineTo(X(t1), Y(f(t0))); ctx.lineTo(X(t1), Y(f(t1)));
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("run = h", (X(t0) + X(t1)) / 2 - 20, Y(f(t0)) + 15);
ctx.fillText("rise", X(t1) + 5, (Y(f(t0)) + Y(f(t1))) / 2);

// the two points
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(t0), Y(f(t0)), 4.5, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(t1), Y(f(t1)), 4.5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("t0", X(t0) - 6, Y(f(t0)) + 18);
ctx.fillText("t0 + h", X(t1) - 16, Y(f(t1)) - 10);

out.note = "secant slope = " + mSec.toFixed(3) + " m/s   |   true v(t0) = " + mTan.toFixed(3) + " m/s   |   gap = " + Math.abs(mSec - mTan).toFixed(3);

// x(t) = 12t - t^3 above, v(t) = 12 - 3t^2 below. Static diagram.
var f = function (s) { return 12 * s - s * s * s; };
var g = function (s) { return 12 - 3 * s * s; };
var tMin = 0, tMax = 3.6;
var padL = 44, padR = 14;
var gap = 18;
var hTop = (H - gap - 34) * 0.56;
var hBot = (H - gap - 34) * 0.44;
var topY0 = 10, botY0 = 10 + hTop + gap;

var X = function (s) { return padL + (s - tMin) / (tMax - tMin) * (W - padL - padR); };
var YT = function (y) { return topY0 + (20 - y) / (20 - (-10)) * hTop; };
var YB = function (y) { return botY0 + (14 - y) / (14 - (-28)) * hBot; };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// frames
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, topY0); ctx.lineTo(padL, topY0 + hTop);
ctx.moveTo(padL, botY0); ctx.lineTo(padL, botY0 + hBot);
ctx.stroke();

// zero lines
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(padL, YT(0)); ctx.lineTo(W - padR, YT(0));
ctx.moveTo(padL, YB(0)); ctx.lineTo(W - padR, YB(0));
ctx.stroke();

// curves
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 200; i++) {
  var s = tMin + (tMax - tMin) * i / 200;
  if (i === 0) ctx.moveTo(X(s), YT(f(s))); else ctx.lineTo(X(s), YT(f(s)));
}
ctx.stroke();
ctx.strokeStyle = C.accent;
ctx.beginPath();
for (var j = 0; j <= 200; j++) {
  var s2 = tMin + (tMax - tMin) * j / 200;
  if (j === 0) ctx.moveTo(X(s2), YB(g(s2))); else ctx.lineTo(X(s2), YB(g(s2)));
}
ctx.stroke();
ctx.lineWidth = 1;

// the marker at t = 2
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(X(2), topY0); ctx.lineTo(X(2), botY0 + hBot);
ctx.stroke();
ctx.setLineDash([]);

// horizontal tangent at the peak
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(X(1.2), YT(16)); ctx.lineTo(X(2.8), YT(16));
ctx.stroke();
ctx.lineWidth = 1;

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(2), YT(16), 4.5, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(2), YB(0), 4.5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("x(t) = 12t - t^3", X(0.1), YT(19));
ctx.fillText("peak x = 16 m", X(2) + 8, YT(16) - 8);
ctx.fillText("v(t) = dx/dt = 12 - 3t^2", X(0.1), YB(12));
ctx.fillText("v = 0 at t = 2 s", X(2) + 8, YB(0) - 8);
ctx.fillStyle = C.faint;
ctx.fillText("x (m)", 4, topY0 + 12);
ctx.fillText("v (m/s)", 4, botY0 + 12);
ctx.fillText("t (s)", W - padR - 28, botY0 + hBot + 20);
ctx.fillText("v > 0: x rising", X(0.15), YB(-14));
ctx.fillText("v < 0: x falling", X(2.15), YB(-22));

// Ladder of length L, base dragged out at constant speed u.
var L = p.L;
var u = p.u;

// base position, looping: x goes from 0.4 up to just under L
var xStart = 0.4;
var span = (L - 0.25) - xStart;
var period = span / u;
var x = xStart + u * (t % period);
var y = Math.sqrt(Math.max(L * L - x * x, 1e-6));
var vy = -x * u / y;                  // dy/dt
var ay = -(u * u) * (L * L) / (y * y * y); // d2y/dt2

var padL = 60, padB = 34, padT = 18, padR = 110;
var sx = (W - padL - padR) / (L * 1.1);
var sy = (H - padT - padB) / (L * 1.1);
var s = Math.min(sx, sy);
var X = function (q) { return padL + q * s; };
var Y = function (q) { return H - padB - q * s; };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// ground and wall
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(padL - 12, Y(0)); ctx.lineTo(W - padR + 10, Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(L * 1.05)); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("wall", X(0) - 34, Y(L * 0.9));
ctx.fillText("floor", W - padR - 18, Y(0) + 18);

// ladder
ctx.strokeStyle = C.accent;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(X(x), Y(0)); ctx.lineTo(X(0), Y(y)); ctx.stroke();
ctx.lineWidth = 1;

// end dots
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(x), Y(0), 4.5, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(0), Y(y), 4.5, 0, Math.PI * 2); ctx.fill();

// leg labels
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(0), Y(-0.12)); ctx.lineTo(X(x), Y(-0.12)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("x = " + x.toFixed(2) + " m", X(x / 2) - 26, Y(0) + 26);
ctx.fillText("y = " + y.toFixed(2) + " m", X(0) + 8, Y(y / 2));
ctx.fillStyle = C.figure;
ctx.fillText("L = " + L.toFixed(1) + " m", X(x / 2) - 6, Y(y / 2) - 6);

// velocity arrows
var arrow = function (x0, y0, dx, dy, label) {
  ctx.strokeStyle = C.figure;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0 + dx, y0 + dy); ctx.stroke();
  var ang = Math.atan2(dy, dx);
  ctx.beginPath();
  ctx.moveTo(x0 + dx, y0 + dy);
  ctx.lineTo(x0 + dx - 7 * Math.cos(ang - 0.4), y0 + dy - 7 * Math.sin(ang - 0.4));
  ctx.lineTo(x0 + dx - 7 * Math.cos(ang + 0.4), y0 + dy - 7 * Math.sin(ang + 0.4));
  ctx.closePath();
  ctx.fillStyle = C.figure;
  ctx.fill();
  ctx.lineWidth = 1;
  ctx.fillStyle = C.figure;
  ctx.fillText(label, x0 + dx + 6, y0 + dy + 4);
};
arrow(X(x), Y(0), 30 * u, 0, "u");
arrow(X(0), Y(y), 0, Math.min(70, 22 * Math.abs(vy)), "dy/dt");

// speed bar for the top
var bx = W - padR + 26;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(bx, Y(0)); ctx.lineTo(bx, Y(L)); ctx.stroke();
var frac = Math.min(1, Math.abs(vy) / (4 * u));
ctx.strokeStyle = C.accent;
ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(bx, Y(0)); ctx.lineTo(bx, Y(L * frac)); ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.faint;
ctx.fillText("top speed", bx - 18, Y(L) - 6);

out.note = "x = " + x.toFixed(2) + " m, y = " + y.toFixed(2) + " m  |  dy/dt = " + vy.toFixed(3) + " m/s  |  top acceleration = " + ay.toFixed(3) + " m/s^2";
